head.b:skin:
:root{--bg:#080d19;--panel:#111a2c;--panel2:#17243a;--ink:#eef4ff;--muted:#93a4bf;--line:rgba(174,198,255,.16);--cyan:#59e1ff;--violet:#9c83ff;--pink:#ff78b7;--good:#54dfa4;--bad:#ff7188;--shadow:0 24px 70px rgba(0,0,0,.38)}
#authCard,#userDashboard,#adminDashboard{display:none!important}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(ellipse at 12% 0%,#182c50 0,transparent 38%),radial-gradient(ellipse at 92% 12%,#30204c 0,transparent 32%),var(--bg);color:var(--ink);font:15px/1.55 Inter,system-ui,-apple-system,Segoe UI,sans-serif;min-height:100vh}button,input,textarea{font:inherit}button{cursor:pointer}.site-wrap{max-width:1180px;margin:auto;padding:22px 22px 110px}.topbar{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 0 28px}.brand{display:flex;align-items:center;gap:12px;font-size:19px;font-weight:800;letter-spacing:-.5px}.brand-mark{width:42px;height:42px;border-radius:14px;background:linear-gradient(135deg,var(--cyan),var(--violet));display:grid;place-items:center;color:#08101e;font-size:21px;box-shadow:0 0 28px #59e1ff55}.top-actions{display:flex;align-items:center;gap:10px}.clock{font-variant-numeric:tabular-nums;color:#c5d5ef;background:#ffffff0a;border:1px solid var(--line);padding:9px 13px;border-radius:12px;font-size:13px}.btn{border:0;border-radius:13px;padding:11px 17px;font-weight:750;color:#07111e;background:linear-gradient(110deg,var(--cyan),#9aafff);box-shadow:0 8px 26px #59e1ff25;transition:.2s}.btn:hover{transform:translateY(-2px);filter:brightness(1.08)}.btn.ghost{background:#ffffff0a;border:1px solid var(--line);color:var(--ink);box-shadow:none}.btn.danger{background:#ff71881b;color:#ff9bab;border:1px solid #ff71884d;box-shadow:none}.hero{display:grid;grid-template-columns:1.15fr .85fr;gap:30px;align-items:center;padding:42px 0 38px}.eyebrow{color:var(--cyan);font-size:12px;letter-spacing:2px;text-transform:uppercase;font-weight:800}.hero h1{font-size:clamp(36px,5.2vw,66px);line-height:1.06;letter-spacing:-2.8px;margin:14px 0 18px}.gradient-text{background:linear-gradient(90deg,#fff,var(--cyan),#c6a9ff);-webkit-background-clip:text;background-clip:text;color:transparent}.hero p{max-width:570px;color:var(--muted);font-size:17px}.hero-card,.panel,.auth-card,.stat{background:linear-gradient(145deg,#ffffff12,#ffffff05);border:1px solid var(--line);border-radius:24px;box-shadow:var(--shadow);backdrop-filter:blur(20px)}.hero-card{padding:25px;min-height:260px;position:relative;overflow:hidden}.hero-card:before{content:'';position:absolute;width:220px;height:220px;border-radius:50%;background:#59e1ff25;filter:blur(45px);right:-60px;top:-70px}.cloud-icon{font-size:56px;position:relative}.hero-card h3{font-size:21px;margin:15px 0 5px}.hero-card p{font-size:14px;margin:0;color:var(--muted)}.feature-row{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin:12px 0 42px}.feature{padding:17px;border:1px solid var(--line);border-radius:17px;background:#ffffff08}.feature b{display:block;margin:7px 0 3px}.feature span{font-size:13px;color:var(--muted)}.section-head{display:flex;justify-content:space-between;align-items:end;gap:12px;margin:32px 0 15px}.section-head h2{font-size:24px;margin:0}.section-head p{margin:4px 0 0;color:var(--muted);font-size:13px}.auth-card{max-width:470px;margin:15px auto 35px;padding:28px;position:relative;overflow:hidden}.auth-card:before{content:'';position:absolute;inset:-2px;background:linear-gradient(120deg,#59e1ff22,transparent 40%,#a184ff22);pointer-events:none}.auth-inner{position:relative}.auth-tabs{display:flex;padding:5px;background:#060c18;border:1px solid var(--line);border-radius:14px;margin:18px 0}.auth-tab{flex:1;background:transparent;border:0;color:var(--muted);padding:10px;border-radius:10px;font-weight:700}.auth-tab.active{color:#08111f;background:linear-gradient(100deg,var(--cyan),#b4a2ff)}.field{margin:14px 0}.field label{display:block;color:#b8c8e1;font-size:13px;margin:0 0 7px}.field input,.search-input{width:100%;border:1px solid var(--line);background:#070e1c;color:var(--ink);border-radius:12px;padding:13px 14px;outline:none}.field input:focus,.search-input:focus{border-color:var(--cyan);box-shadow:0 0 0 3px #59e1ff19}.full{width:100%}.hint{font-size:12px;color:var(--muted);margin-top:10px}.notice{padding:11px 13px;border-radius:12px;margin:12px 0;font-size:13px;display:none}.notice.show{display:block}.notice.ok{background:#54dfa41a;color:#8ff0c6;border:1px solid #54dfa44a}.notice.err{background:#ff71881a;color:#ff9bab;border:1px solid #ff71884a}.dashboard{display:none;margin:35px 0}.dashboard.active{display:block}.dash-grid{display:grid;grid-template-columns:230px 1fr;gap:18px}.side{padding:18px;height:max-content;position:sticky;top:15px}.side h3{margin:0 0 14px}.side-link{display:block;width:100%;text-align:left;padding:11px 12px;border:0;background:transparent;color:#c5d4ea;border-radius:11px;margin:3px 0}.side-link.active,.side-link:hover{background:#59e1ff16;color:var(--cyan)}.content-panel{padding:22px;min-width:0}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:18px}.stat{padding:17px;border-radius:17px;box-shadow:none}.stat small{color:var(--muted)}.stat strong{display:block;font-size:25px;margin-top:5px}.upload-zone{border:1.5px dashed #59e1ff66;background:#59e1ff09;border-radius:18px;padding:28px;text-align:center;margin:15px 0}.upload-zone.drag{background:#59e1ff1d;border-color:var(--cyan)}.upload-zone input{display:none}.file-list{display:grid;gap:10px;margin-top:15px}.file-row{display:flex;align-items:center;gap:12px;padding:13px;border:1px solid var(--line);border-radius:14px;background:#ffffff07}.file-icon{width:42px;height:42px;border-radius:12px;background:#59e1ff16;display:grid;place-items:center;font-size:20px}.file-meta{flex:1;min-width:0}.file-meta b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.file-meta small{color:var(--muted)}.file-actions{display:flex;gap:7px}.mini{padding:8px 10px;border-radius:10px;border:1px solid var(--line);background:#ffffff0a;color:var(--ink);font-size:12px}.admin-only{display:none}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:550px}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line);font-size:13px}th{color:var(--muted);font-weight:600}.mobile-nav{display:none}.blogger-posts{margin-top:35px}.blogger-posts .widget{display:none}
@media(max-width:760px){.site-wrap{padding:14px 15px 110px}.topbar{padding-bottom:12px}.clock{font-size:11px;padding:7px 9px}.top-actions .btn{padding:9px 11px;font-size:12px}.hero{grid-template-columns:1fr;padding:27px 0 22px;gap:18px}.hero h1{font-size:42px;letter-spacing:-1.8px}.hero p{font-size:15px}.hero-card{min-height:190px}.feature-row{grid-template-columns:1fr;gap:9px;margin-bottom:28px}.feature{display:flex;align-items:center;gap:12px}.feature b{margin:0}.feature span{display:block}.dash-grid{grid-template-columns:1fr}.side{display:none}.content-panel{padding:15px}.stats{grid-template-columns:repeat(3,1fr);gap:7px}.stat{padding:12px}.stat strong{font-size:20px}.stat small{font-size:11px}.auth-card{padding:20px;margin-top:10px}.file-row{align-items:flex-start}.file-actions{flex-direction:column}.mobile-nav{position:fixed;z-index:50;bottom:max(12px,env(safe-area-inset-bottom));left:50%;transform:translateX(-50%);display:flex;gap:4px;padding:7px;border-radius:22px;background:#17243acc;border:1px solid #ffffff25;box-shadow:0 12px 45px #0009;backdrop-filter:blur(24px);width:min(94%,430px);justify-content:space-around}.mobile-nav button{border:0;background:transparent;color:#aabbd5;padding:9px 12px;border-radius:15px;display:grid;gap:2px;justify-items:center;font-size:10px;min-width:58px}.mobile-nav button span:first-child{font-size:18px}.mobile-nav button.active{color:#07111f;background:linear-gradient(120deg,var(--cyan),#b8a6ff)}.section-head{align-items:start;flex-direction:column}.file-meta small{font-size:11px}}
@media(max-width:380px){.hero h1{font-size:35px}.brand{font-size:16px}.stats{grid-template-columns:1fr 1fr}.stats .stat:last-child{grid-column:span 2}}

body.script:
//
const API_BASE='https://file-hosting-1oe4.onrender.com';
let authToken='', currentUser=null, allFiles=[], authMode='login';
const $=id=>document.getElementById(id);
function api(path,opts={}){opts.headers=opts.headers||{};if(authToken)opts.headers.Authorization='Bearer '+authToken;return fetch(API_BASE+path,opts).then(async r=>{let d={};try{d=await r.json()}catch(e){}if(!r.ok)throw Error(d.error||'Request failed');return d})}
function showNotice(id,msg,type='err'){let n=$(id);n.textContent=msg;n.className='notice show '+(type==='ok'?'ok':'err')}
function hideAuth(){$('authCard').style.display='none';$('hero').style.display='grid';$('features').style.display='grid'}
function showAuth(){$('hero').style.display='none';$('features').style.display='none';$('authCard').style.display='block';$('userDashboard').classList.remove('active');$('adminDashboard').classList.remove('active')}
function setAuthMode(mode){authMode=mode;$('tabLogin').classList.toggle('active',mode==='login');$('tabRegister').classList.toggle('active',mode==='register');$('loginFields').style.display=mode==='login'?'block':'none';$('registerFields').style.display=mode==='register'?'block':'none';$('authTitle').textContent=mode==='login'?'Access your workspace':'Create your account';$('authSub').textContent=mode==='login'?'Use your personal login code.':'Enter the one-time invite code from the administrator.';$('authNotice').className='notice'}
async function loginWithCode(){let code=$('loginCode').value.trim();if(!code)return showNotice('authNotice','Enter your personal login code.');try{let d=await api('/api/auth/code-login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({login_code:code})});authToken=d.token;localStorage.setItem('somrat_token',authToken);currentUser=d.user;afterLogin()}catch(e){showNotice('authNotice',e.message)}}
async function registerWithInvite(){let invite=$('inviteCode').value.trim(),name=$('displayName').value.trim();if(!invite)return showNotice('authNotice','Enter your invite code.');try{let d=await api('/api/auth/invite-register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({invite_code:invite,display_name:name})});if(d.login_code){$('authNotice').className='notice show ok';$('authNotice').textContent='Account created. Your personal login code: '+d.login_code+' — save it now. Then sign in.';$('loginCode').value=d.login_code;setAuthMode('login')}else throw Error('The server did not return a login code.')}catch(e){showNotice('authNotice',e.message)}}
async function afterLogin(){ $('authCard').style.display='none';$('hero').style.display='none';$('features').style.display='none';$('headerLogin').style.display='none';$('headerLogout').style.display='inline-block';if(currentUser&&currentUser.role==='admin'){$('adminDashboard').classList.add('active');$('userDashboard').classList.remove('active');loadAdmin()}else{$('userDashboard').classList.add('active');$('adminDashboard').classList.remove('active');$('welcomeName').textContent='Welcome, '+(currentUser.username||'User');loadFiles()} }
async function restoreSession(){if(!authToken)return;try{let d=await api('/api/me');if(d.user){currentUser=d.user;afterLogin()}else{authToken='';localStorage.removeItem('somrat_token')}}catch(e){authToken='';localStorage.removeItem('somrat_token')}}
async function logoutUser(){try{await api('/api/auth/logout',{method:'POST'})}catch(e){}authToken='';currentUser=null;allFiles=[];localStorage.removeItem('somrat_token');$('userDashboard').classList.remove('active');$('adminDashboard').classList.remove('active');$('headerLogin').style.display='inline-block';$('headerLogout').style.display='none';$('hero').style.display='grid';$('features').style.display='grid';$('authCard').style.display='none'}
async function loadFiles(){try{let d=await api('/api/files');allFiles=d.files||[];renderFiles()}catch(e){$('fileList').textContent=e.message}}
function renderFiles(){let q=($('fileSearch').value||'').toLowerCase(),rows=allFiles.filter(f=>f.name.toLowerCase().includes(q));$('fileCount').textContent=allFiles.length;$('fileList').innerHTML=rows.length?rows.map(f=>`<div class="file-row"><div class="file-icon">${f.kind==='image'?'▧':f.kind==='video'?'▷':'▤'}</div><div class="file-meta"><b>${esc(f.name)}</b><small>${fmtSize(f.size)} · ${new Date(f.created_at).toLocaleDateString()}</small></div><div class="file-actions"><button class="mini" onclick="copyShare('${escAttr(f.share_code)}')">Copy link</button><button class="mini" onclick="renameFile(${Number(f.id)},'${escAttr(f.name)}')">Rename</button><button class="mini" onclick="deleteFile(${Number(f.id)})">Delete</button></div></div>`).join(''):'<p style="color:var(--muted)">No files found. Upload your first file above.</p>'}
function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function escAttr(s){return esc(s).replace(/`/g,'')}
function fmtSize(n){n=Number(n)||0;return n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB'}
async function uploadSelected(files){if(!files||!files.length)return;let fd=new FormData();const selected=Array.from(files).filter(f=>f.type.startsWith('image/')).slice(0,2);if(!selected.length){$('uploadStatus').textContent='Please choose image files.';return}let previews=selected.map(f=>'<div style="width:110px"><img alt="Selected image preview" style="width:110px;height:85px;object-fit:cover;border-radius:12px;border:1px solid var(--line)" src="'+URL.createObjectURL(f)+'"><small style="display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(f.name)+'</small></div>').join('');$('imagePreview').innerHTML=previews;selected.forEach(f=>fd.append('files',f));$('uploadStatus').textContent='Uploading '+selected.length+' image(s) to '+(currentUser?.username||'your account')+'…';try{let d=await api('/api/files',{method:'POST',body:fd});$('uploadStatus').textContent=(d.files||[]).length+' file(s) uploaded successfully.';await loadFiles()}catch(e){$('uploadStatus').textContent=e.message} $('filePicker').value=''}
async function guestUpload(files){
  const selected=Array.from(files||[]).filter(f=>f.type.startsWith('image/')).slice(0,2);
  if(!selected.length){$('guestStatus').textContent='দয়া করে অন্তত একটি ছবি নির্বাচন করুন।';return;}
  const fd=new FormData();selected.forEach(f=>fd.append('files',f));
  $('guestPreview').innerHTML=selected.map(f=>'<img alt="ছবির প্রিভিউ" style="width:110px;height:85px;object-fit:cover;border-radius:12px;border:1px solid var(--line)" src="'+URL.createObjectURL(f)+'">').join('');
  $('guestLinks').innerHTML='';$('guestStatus').textContent='ছবি আপলোড হচ্ছে…';
  try{const d=await fetch(API_BASE+'/api/public/upload',{method:'POST',body:fd});const j=await d.json();if(!d.ok)throw Error(j.error||'আপলোড ব্যর্থ হয়েছে');
    $('guestStatus').textContent='আপলোড সফল! নিচের লিংক কপি বা শেয়ার করুন।';
    $('guestLinks').innerHTML=(j.files||[]).map(f=>'<div class="file-row"><div class="file-meta"><b>'+esc(f.name)+'</b><small>আপলোড সম্পন্ন</small></div><button class="mini guest-copy" type="button">লিংক কপি</button><a class="mini" target="_blank" rel="noopener" href="'+escAttr(f.share_url)+'">ছবি খুলুন</a></div>').join('');Array.from($('guestLinks').querySelectorAll('.guest-copy')).forEach((b,i)=>b.addEventListener('click',()=>copyGuestLink((j.files||[])[i].share_url)));
  }catch(e){$('guestStatus').textContent=e.message;} $('guestFilePicker').value='';
}
async function copyGuestLink(url){try{await navigator.clipboard.writeText(url);$('guestStatus').textContent='লিংক কপি হয়েছে!'}catch(e){prompt('লিংক কপি করুন',url)}}
async function copyShare(code){let url=API_BASE+'/api/share/'+code+'/raw';try{await navigator.clipboard.writeText(url);alert('Share link copied')}catch(e){prompt('Copy this link',url)}}
async function renameFile(id,old){let name=prompt('New file name',old);if(!name||name===old)return;try{await api('/api/files/'+id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});loadFiles()}catch(e){alert(e.message)}}
async function deleteFile(id){if(!confirm('Delete this file?'))return;try{await api('/api/files/'+id,{method:'DELETE'});loadFiles()}catch(e){alert(e.message)}}
async function loadAdmin(){try{let [s,u,f]=await Promise.all([api('/api/admin/stats'),api('/api/admin/users'),api('/api/admin/files')]);$('adminUsers').textContent=s.stats.users??u.users.length;$('adminFiles').textContent=s.stats.files??f.files.length;$('adminStorage').textContent=fmtSize(s.stats.bytes||0);$('usersBody').innerHTML=(u.users||[]).map(x=>`<tr><td>${esc(x.username)}</td><td>${x.banned?'Blocked':'Active'}</td><td>${x.created_at?new Date(x.created_at).toLocaleDateString():'—'}</td><td><button class="mini" onclick="banUser(${Number(x.id)},${!x.banned})">${x.banned?'Unblock':'Block'}</button></td></tr>`).join('');$('adminFilesBody').innerHTML=(f.files||[]).map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.owner||'')}</td><td>${fmtSize(x.size)}</td><td><a style="color:var(--cyan)" target="_blank" href="${API_BASE}/api/share/${encodeURIComponent(x.share_code)}/raw">Open</a></td></tr>`).join('')}catch(e){console.error(e);alert('Admin data: '+e.message)}}
function adminTab(t,el){['adminOverview','adminInvites','adminUsersTable','adminFilesTable'].forEach((id,i)=>$(id).style.display=(['overview','invites','users','files'][i]===t?'block':'none'));document.querySelectorAll('.side-link').forEach(x=>x.classList.remove('active'));if(el)el.classList.add('active')}
async function createInvite(){let code=$('newInvite').value.trim();try{let d=await api('/api/admin/invites',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code})});$('inviteResult').innerHTML='<div class="file-row"><b>'+esc(d.invite_code||d.code||'Invite created')+'</b><button class="mini" onclick="navigator.clipboard.writeText(this.previousElementSibling.textContent)">Copy</button></div>';showNotice('inviteNotice','Invite code created. Share it securely.','ok')}catch(e){showNotice('inviteNotice',e.message)}}
async function banUser(id,banned){try{await api('/api/admin/users/'+id+'/ban',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({banned})});loadAdmin()}catch(e){alert(e.message)}}
function switchDash(t,el){$('uploadArea').style.display=t==='upload'?'block':'none';$('fileList').style.display=t==='account'?'none':'grid';$('accountArea').style.display=t==='account'?'block':'none';if(t==='account')$('accountName').textContent='Signed in as '+(currentUser?.username||'');document.querySelectorAll('.side-link').forEach(x=>x.classList.remove('active'));if(el)el.classList.add('active')}
function navTo(t,el){document.querySelectorAll('.mobile-nav button').forEach(x=>x.classList.remove('active'));el.classList.add('active');if(t==='home'){logoutUser();return}if(!currentUser){showAuth();return}if(t==='upload')$('uploadArea').scrollIntoView({behavior:'smooth'});else if(t==='files')$('fileList').scrollIntoView({behavior:'smooth'});else $('accountArea').scrollIntoView({behavior:'smooth'})}
function tick(){let d=new Date();$('liveClock').textContent=d.toLocaleTimeString('en-US',{hour12:true});$('yearNow').textContent=d.getFullYear()}setInterval(tick,1000);tick();
let dz=$('dropZone');['dragenter','dragover'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.add('drag')}));['dragleave','drop'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.remove('drag')}));dz.addEventListener('drop',e=>uploadSelected(e.dataTransfer.files));
// Public guest uploader: no account or registration required.
//
